head.script:
// 담당 범위 : dateValidSet true / false / 미설정, dateValidCheck 연동, 이전 입력값 없음, Empty String 입력, dateValidSetCustom 연동
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외
//    (편집 입력이 가능한 Body Column 전용 속성이며 Header / SubTotal / Footer Column 은 입력 수단이 없어 설정 영역 con 옵션 미생성)



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > dateValidSet]<br/>inputType='calendar' 인 Column 에 유효하지 않은 날짜/시간이 입력된 경우 이전 입력값으로 복원할지 설정합니다.",
    "validation" : [
        "true 설정 시, 유효하지 않은 날짜/시간(Empty String 불포함)이 Column 에 입력된 경우 Column 의 dateValidCheck 속성값이 true 로 동작합니다.",
        "true 설정 시, 유효하지 않은 날짜/시간(Empty String 불포함)이 Column 에 입력된 경우 Cell 값이 이전 입력값으로 복원되고 해당 Cell 에 포커스가 유지됩니다.",
        "true 설정 시, 유효하지 않은 날짜/시간(Empty String 불포함)이 Column 에 입력된 경우 이전 입력값이 없으면 ''(Empty String)이 설정됩니다.",
        "false 설정 시, 유효하지 않은 날짜/시간(Empty String 불포함)이 입력되어도 이전 입력값으로 복원하지 않습니다.",
        "false 설정 시, Column 의 dateValidCheck 속성에 설정된 값에 맞게 동작합니다.",
        "미설정 시, 유효하지 않은 날짜/시간(Empty String 불포함)이 입력되어도 이전 입력값으로 복원하지 않습니다.",
        "dateValidSet=true 인 Column 에서 입력값이 ''(Empty String)이면 정상적으로 종료됩니다.",
        "Column 의 dateValidSetCustom=true 이면 dateValidSet=true 여도 입력값 복원과 메시지 표시를 모두 수행하지 않습니다.",
    ]
}

// 편집 종료 결과 출력 지연 타이머
scwin.editEndTimer = null;



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // validation 1, 5, 8 : 엔진이 표시하는 alert 문구를 결과창에 기록 (기록 후 원래 alert 도 그대로 실행, 페이지 종료 시 원복)
    scwin.orgAlert = window.alert;
    window.alert = function (msg) {
        wf_body_bottom.getObj("scwin").setReturnValue("alert : " + msg);
        return scwin.orgAlert.apply(window, arguments);
    };

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (dateValidSet=true, dateValidCheck=false, dateValidSetCustom 미설정)
    con_dateValidSet.setValue("2");
    con_dateValidCheck.setValue("3");
    con_dateValidSetCustom.setValue("1");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 페이지 종료 시 alert 후킹 원복
scwin.onpageunload = function () {
    if (scwin.orgAlert) {
        window.alert = scwin.orgAlert;
    }
};



// comp 생성
//  - cal : 검증 대상 Body Column (inputType="calendar" + dataType="date", calendarValueType="yearMonthDate")
//          dateValidSet / dateValidCheck / dateValidSetCustom 는 con (미설정이면 속성 자체를 넣지 않음)
//  - Row 0 은 이전 입력값 20261001, Row 1 은 이전 입력값 없음(빈값)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] cal Row 0 은 20261001, Row 1 은 빈값\n[절차] 결과창 clear -> cal 셀 클릭 -> Ctrl+A 후 유효하지 않은 날짜(예: 20261345) 입력 또는 Backspace 로 값 삭제 -> 셀 밖(조건 영역) 클릭\n[확인] alert 문구, 편집 종료 결과 줄의 편집 유지 여부와 포커스 위치(입력창 값), DataList 값\n편집이 유지되면 Esc 로 편집을 취소하거나 셀 밖을 한 번 더 클릭한 뒤 Target 재생성"', '', 'label1');

    // dataList 생성 (calendar Column 바인딩 컬럼은 dataType="date")
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cal" name="cal" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "cal" : "20261001" },
        { "cal" : "" }
    ], false);

    // con 값 (gdl_boolean 은 라벨로 읽고, 미설정이면 속성 자체를 넣지 않는다)
    let properties = {
        dateValidSet : con_dateValidSet.getText(),
        dateValidCheck : con_dateValidCheck.getText(),
        dateValidSetCustom : con_dateValidSetCustom.getText()
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oneditend"]);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:120px;" ' + eList + '>';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="260" style="" inputType="text" id="column1" value="cal"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="260" style="" id="cal" inputType="calendar" dataType="date" viewType="icon" calendarValueType="yearMonthDate" ' + cList + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1 ~ 8 : 셀 밖 클릭으로 편집 종료를 시도한 뒤의 결과 (편집 유지 여부, 포커스 위치와 입력창 값, DataList 값)
//  - 같은 클릭에서 여러 번 발생해도 마지막 상태 1줄만 출력
scwin.target1_oneditend = function (rowIndex, columnIndex, value) {
    clearTimeout(scwin.editEndTimer);
    scwin.editEndTimer = setTimeout(function () {
        scwin.printEditResult(rowIndex, value);
    }, 300);
}



scwin.printEditResult = function (rowIndex, value) {
    let activeEl = document.activeElement;
    let strFocus = "";
    if (activeEl && target1.render.contains(activeEl) && activeEl.tagName === "INPUT") {
        strFocus = "Row " + target1.getFocusedRowIndex() + " cal 입력창 (입력창 값 '" + activeEl.value + "')";
    } else {
        strFocus = "그리드 밖";
    }
    let arrData = [];
    let rowCnt = dlt_bind.getRowCount();
    for (let i = 0; i < rowCnt; i++) {
        arrData.push("Row " + i + " '" + dlt_bind.getCellData(i, "cal") + "'");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 '" + value + "' -> 편집 유지 : " + target1.isEditing()
        + " / 포커스 : " + strFocus + " / DataList : " + arrData.join(", "));
}
